using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Text;using System.Threading;using System.Security.Cryptography;using System.Collections.Generic;using System.Web.Script.Serialization;
// The launcher and updater share this small, versioned recovery format.
sealed class InstallTransaction : IDisposable {
 public sealed class SavedFile {public string Name;public bool Existed;public string Sha256;}
 public sealed class Journal {public int Format=1;public string Id;public bool Committed;public List<SavedFile> Files=new List<SavedFile>();}
 public static readonly string[] Names={"CodexUsageWidget.exe","WidgetUpdater.exe","Install.ps1","설치.cmd","README.txt","Codex-LICENSE.txt","Codex-NOTICE.txt","LICENSE.txt","installed-version.txt"};
 readonly string root,journalPath;readonly FileStream gate;Journal state;bool finished;
 InstallTransaction(string folder){root=Path.GetFullPath(folder);Directory.CreateDirectory(root);journalPath=Path.Combine(root,".update-transaction.json");try{gate=new FileStream(Path.Combine(root,".update.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}catch(IOException){throw new IOException("설치 또는 업데이트가 진행 중입니다. 잠시 후 다시 실행해 주세요.");}}
 static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","");}
 public static void AtomicCopy(string source,string destination){string temp=destination+"."+Guid.NewGuid().ToString("N")+".pending";try{using(var input=File.OpenRead(source))using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){input.CopyTo(output);output.Flush(true);}if(File.Exists(destination))File.Replace(temp,destination,null);else File.Move(temp,destination);}finally{if(File.Exists(temp))File.Delete(temp);}}
 void Write(){string temp=journalPath+".pending";byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(state));using(var f=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(journalPath))File.Replace(temp,journalPath,null);else File.Move(temp,journalPath);}
 string Backup{get{return Path.Combine(root,".transaction-backups",state.Id);}}
 void Read(){state=new JavaScriptSerializer().Deserialize<Journal>(File.ReadAllText(journalPath));Guid id;if(state==null||state.Format!=1||!Guid.TryParseExact(state.Id,"N",out id)||state.Files==null||state.Files.Count>Names.Length||state.Files.Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=state.Files.Count||state.Files.Any(x=>!Names.Contains(x.Name)||x.Existed&&(x.Sha256==null||x.Sha256.Length!=64)))throw new IOException("설치 복구 기록을 확인하지 못했습니다. 배포 파일로 다시 설치해 주세요.");}
 void Cleanup(){if(File.Exists(journalPath))File.Delete(journalPath);try{foreach(var f in state.Files){string p=Path.Combine(Backup,f.Name);if(File.Exists(p))File.Delete(p);}if(Directory.Exists(Backup))Directory.Delete(Backup,false);}catch{}finished=true;}
 void Restore(){foreach(var f in state.Files.Where(x=>x.Existed))if(!File.Exists(Path.Combine(Backup,f.Name))||Hash(Path.Combine(Backup,f.Name))!=f.Sha256)throw new IOException("이전 버전 복구 파일을 확인하지 못했습니다. 배포 파일로 다시 설치해 주세요.");foreach(var f in state.Files){string dest=Path.Combine(root,f.Name);if(f.Existed)AtomicCopy(Path.Combine(Backup,f.Name),dest);else if(File.Exists(dest))File.Delete(dest);}Cleanup();}
 void RecoverCore(){if(!File.Exists(journalPath))return;Read();if(state.Committed)Cleanup();else Restore();}
 public static bool Recover(string folder){using(var tx=new InstallTransaction(folder)){bool had=File.Exists(tx.journalPath);tx.RecoverCore();return had;}}
 public static InstallTransaction Begin(string folder,IEnumerable<string> files){var tx=new InstallTransaction(folder);try{tx.RecoverCore();tx.finished=false;tx.state=new Journal{Id=Guid.NewGuid().ToString("N")};foreach(string name in files.Distinct(StringComparer.OrdinalIgnoreCase)){if(!Names.Contains(name))throw new IOException("설치 파일 이름을 확인하지 못했습니다.");string p=Path.Combine(tx.root,name);if(Directory.Exists(p))throw new IOException("설치 위치에 같은 이름의 폴더가 있습니다.");tx.state.Files.Add(new SavedFile{Name=name,Existed=File.Exists(p)});}Directory.CreateDirectory(tx.Backup);foreach(var f in tx.state.Files.Where(x=>x.Existed)){string backup=Path.Combine(tx.Backup,f.Name);AtomicCopy(Path.Combine(tx.root,f.Name),backup);f.Sha256=Hash(backup);}tx.Write();return tx;}catch{tx.Dispose();throw;}}
 public void Replace(string source,string name){if(finished||!state.Files.Any(x=>x.Name==name))throw new IOException("설치 파일이 작업 기록과 다릅니다.");AtomicCopy(source,Path.Combine(root,name));}
 public void Commit(){state.Committed=true;Write();Cleanup();}
 public void Rollback(){if(!finished)Restore();}
 public void Dispose(){gate.Dispose();}
 public static Process StartHealthy(string target,string pending,string version,string extra){string ready=Path.Combine(pending,"ready.json");if(File.Exists(ready))File.Delete(ready);Process next=Process.Start(new ProcessStartInfo(target,"--post-update \""+pending+"\" "+extra){WorkingDirectory=Path.GetDirectoryName(target),UseShellExecute=false});try{for(int i=0;i<120&&!next.HasExited;i++){Thread.Sleep(250);try{if(File.Exists(ready)){var state=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(ready));if(Convert.ToString(state["version"])==version&&Convert.ToInt32(state["pid"])==next.Id)return next;}}catch(IOException){}catch(ArgumentException){}}throw new IOException("새 버전이 정상 실행되지 않아 이전 버전으로 복구합니다.");}catch{Stop(next);throw;}}
 public static void Stop(Process process){if(process==null)return;try{if(!process.HasExited){process.Kill();process.WaitForExit(5000);}}catch{} }
}
